type AIAttributionBucketInput string

const (
	AIAttributionBucketInputAiAssisted   AIAttributionBucketInput = "AI_ASSISTED"
	AIAttributionBucketInputAgentCreated AIAttributionBucketInput = "AGENT_CREATED"
	AIAttributionBucketInputAiReview     AIAttributionBucketInput = "AI_REVIEW"
	AIAttributionBucketInputHuman        AIAttributionBucketInput = "HUMAN"
	AIAttributionBucketInputUnknown      AIAttributionBucketInput = "UNKNOWN"
)

var AllAIAttributionBucketInput = []AIAttributionBucketInput{
	AIAttributionBucketInputAiAssisted,
	AIAttributionBucketInputAgentCreated,
	AIAttributionBucketInputAiReview,
	AIAttributionBucketInputHuman,
	AIAttributionBucketInputUnknown,
}

func (e AIAttributionBucketInput) IsValid() bool {
	switch e {
	case AIAttributionBucketInputAiAssisted, AIAttributionBucketInputAgentCreated, AIAttributionBucketInputAiReview, AIAttributionBucketInputHuman, AIAttributionBucketInputUnknown:
		return true
	}
	return false
}

func (e AIAttributionBucketInput) String() string {
	return string(e)
}

func (e *AIAttributionBucketInput) UnmarshalGQL(v any) error {
	str, ok := v.(string)
	if !ok {
		return fmt.Errorf("enums must be strings")
	}

	*e = AIAttributionBucketInput(str)
	if !e.IsValid() {
		return fmt.Errorf("%s is not a valid AIAttributionBucketInput", str)
	}
	return nil
}

func (e AIAttributionBucketInput) MarshalGQL(w io.Writer) {
	fmt.Fprint(w, strconv.Quote(e.String()))
}

